// spec: Реклама — где показывается и где нет (#840d8543 #a5b844f5)
// seed: tests/seed.user.spec.ts
import { test, expect } from '@playwright/test';
import path from 'node:path';
import { startMonitoring, endMonitoring } from '../helpers/monitor';

test.use({ storageState: path.join(__dirname, '../../../auth/user.json') });
test.setTimeout(120_000);

test.describe('Реклама — где показывается и где нет', () => {
  test('Нет рекламы на экране сбоя «המכשיר זז» и в «כיוון מחדש» #840d8543 #a5b844f5 @iphone @data', async ({ page }) => {
    // Подготовка: мок moved → проверка звука → камера → дети → /monitor/live
    await startMonitoring(page, 'moved');

    // Ждём лист сбоя «המכשיר זז»
    await expect(page.getByText('המכשיר זז').filter({ visible: true }).first()).toBeVisible({ timeout: 45_000 });

    // На экране сбоя рекламы нет
    await expect(page.getByText('פרסומת').filter({ visible: true })).toHaveCount(0);

    // Нажимаем «כיוון מחדש»
    await page.getByRole('button', { name: 'כיוון מחדש' }).filter({ visible: true }).click();
    await expect(page.getByRole('heading', { name: 'כוונו את המצלמה מחדש' }).filter({ visible: true })).toBeVisible();
    await expect(page.getByText('פרסומת').filter({ visible: true })).toHaveCount(0);

    // Нажимаем «חזרה לניטור» — возвращаемся на /monitor/live
    await page.getByRole('button', { name: 'חזרה לניטור' }).filter({ visible: true }).click();
    await expect(page).toHaveURL(/\/monitor\/live/);

    // Завершение мониторинга
    await endMonitoring(page);
  });
});
